    # divider color: color that fills an entire row or column
    from collections import Counter
    cnt = Counter()
    for r in range(H):
        for c in range(W):
            cnt[g[r][c]] += 1
    cand = set(cnt)
    div = None
    for c in cand:
        fullrow = any(all(grid[r][j] == c for j in range(W)) for r in range(H))
        fullcol = any(all(grid[i][c] == c for i in range(H)) for c in range(W))
